document.querySelector('#loginForm').onsubmit=async e=>{e.preventDefault();const button=document.querySelector('#loginButton'),status=document.querySelector('#loginStatus');button.disabled=true;status.textContent='Signing in…';try{const r=await fetch('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});const d=await r.json();if(!r.ok)throw Error(d.error||'Sign-in failed.');location.assign('/#os/onboarding');}catch(err){status.textContent=err.message;}finally{button.disabled=false;}};
